    [Parameter]
    public EventCallback<int> OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback<int> OnMoveRight { get; set; }

    private async System.Threading.Tasks.Task OnMoveLeftClick() => await OnMoveLeft.InvokeAsync(Task.Id);
    private async System.Threading.Tasks.Task OnMoveRightClick() => await OnMoveRight.InvokeAsync(Task.Id);
}

@* Inline form for creating a new task within a column *@

@if (!IsVisible)
{
    <button class="btn btn-add-task" @onclick="Show">+ Add Task</button>
}
else
{
    <div class="add-task-form">
        <input type="text" placeholder="Title" @bind="title" class="form-input" />
        <input type="text" placeholder="Assignee" @bind="assignee" class="form-input" />
        <select @bind="priority" class="form-input">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
        <input type="date" @bind="dueDate" class="form-input" />
        <div class="form-actions">
            <button class="btn btn-save" @onclick="Save" disabled="@isSaving">Save</button>
            <button class="btn btn-cancel" @onclick="Cancel" disabled="@isSaving">Cancel</button>
        </div>
