    [Parameter]
    public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate, string Status)> OnTaskSave { get; set; }
}

@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<div class="board-page">
    <h1>Kanban Board</h1>

    @if (isLoading)
    {
        <div class="board-loading">Loading tasks...</div>
    }
    else if (errorMessage is not null)
    {
        <div class="board-error">
            <p>@errorMessage</p>
            <button class="btn" @onclick="LoadTasks">Retry</button>
        </div>
    }
    else
    {
        <BoardStatsBar Tasks="allTasks" />
        <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

        <div class="board-columns">
            <BoardColumn ColumnName="To Do"
                         Tasks="@GetFilteredTasks("To Do")"
                         ShowMoveLeft="false"
                         ShowMoveRight="true"
                         OnMoveRight="@(id => MoveTask(id, "In Progress"))"
                         OnTaskSave="HandleTaskSave" />

            <BoardColumn ColumnName="In Progress"
                         Tasks="@GetFilteredTasks("In Progress")"
                         ShowMoveLeft="true"
                         ShowMoveRight="true"
                         OnMoveLeft="@(id => MoveTask(id, "To Do"))"
                         OnMoveRight="@(id => MoveTask(id, "Done"))"
                         OnTaskSave="HandleTaskSave" />

            <BoardColumn ColumnName="Done"
                         Tasks="@GetFilteredTasks("Done")"
                         ShowMoveLeft="true"
                         ShowMoveRight="false"
                         OnMoveLeft="@(id => MoveTask(id, "In Progress"))"
                         OnTaskSave="HandleTaskSave" />
        </div>
    }
</div>

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);

        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }

        return tasks.ToList();
    }

    private void HandleSearchChanged(string text)
    {
        searchText = text;
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            allTasks = allTasks.Select(t => t.Id == taskId ? t with { Status = newStatus } : t).ToList();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleTaskSave((string Title, string Assignee, string Priority, DateTime DueDate, string Status) data)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
            allTasks.Add(newTask with { Status = data.Status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

